# generated by ministack, usage: eval "$(ministack --config <file> --env)"
{%- if services.nomad.enabled %}
{%- if services.nomad.servers and nomad_host_port %}
export NOMAD_ADDR='{{ nomad_scheme }}://127.0.0.1:{{ nomad_host_port }}'
{%- elif services.nomad.servers %}
export NOMAD_ADDR='{{ nomad_scheme }}://{{ nomad_server_ip }}:4646'
{%- elif services.nomad.clients %}
export NOMAD_ADDR='{{ nomad_scheme }}://{{ nomad_client_ip }}:4646'
{%- endif %}
{%- if nomad_tls %}
export NOMAD_CACERT='{{ ministack_dir }}/tls/ca.pem'
{%- endif %}
{%- if nomad_acl %}
export NOMAD_TOKEN='{{ nomad_token }}'
{%- endif %}
{%- endif %}
{%- if services.consul.enabled and services.consul.servers %}
{%- if consul_host_port %}
export CONSUL_HTTP_ADDR='{{ consul_scheme }}://127.0.0.1:{{ consul_host_port }}'
{%- else %}
export CONSUL_HTTP_ADDR='{{ consul_scheme }}://{{ consul_server_ip }}:{{ consul_port }}'
{%- endif %}
{%- if consul_tls %}
export CONSUL_CACERT='{{ ministack_dir }}/tls/ca.pem'
{%- endif %}
{%- if consul_acl %}
export CONSUL_HTTP_TOKEN='{{ consul_token }}'
{%- endif %}
{%- endif %}
{%- if services.vault.enabled %}
{%- if vault_host_port %}
export VAULT_ADDR='{{ vault_scheme }}://127.0.0.1:{{ vault_host_port }}'
{%- else %}
export VAULT_ADDR='{{ vault_scheme }}://{{ vault_ip }}:8200'
{%- endif %}
{%- if vault_tls %}
export VAULT_CACERT='{{ ministack_dir }}/tls/ca.pem'
{%- endif %}
export VAULT_TOKEN='{{ vault_root_token }}'
{%- endif %}
